-- a concept check, an applied decision, and an uncertainty/discipline prompt.
INSERT INTO daily_focus_questions (id, chapter, topic, difficulty, type, body, is_active) VALUES
('DF2-KO252-CHART-01','Reading Trading Charts','chart_literacy','beginner','multiple_choice',$json${"type":"multiple_choice","difficulty":"beginner","question":"What does the body of a candle show?","options":["The distance between open and close","Only the highest price","Only the trading volume","A guaranteed future direction"],"answer":"The distance between open and close","explanation":"The candle body connects its opening and closing prices; it is not a forecast.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"beginner","question":"What does the body of a candle show?","options":["The distance between open and close","Only the highest price","Only the trading volume","A guaranteed future direction"],"answer":"The distance between open and close","explanation":"The candle body connects its opening and closing prices; it is not a forecast.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"beginner","question":"Apa yang ditunjukkan oleh body candle?","options":["Jarak antara harga pembukaan dan penutupan","Hanya harga tertinggi","Hanya volume perdagangan","Arah masa depan yang terjamin"],"answer":"Jarak antara harga pembukaan dan penutupan","explanation":"Body candle menghubungkan harga pembukaan dan penutupan; ini bukan ramalan.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-CHART-02','Reading Trading Charts','chart_literacy','intermediate','true_false',$json${"type":"true_false","difficulty":"intermediate","question":"A support level is an exact price that guarantees a rebound.","answer":false,"explanation":"Support is a zone of past reactions, not a guaranteed floor or an automatic buy signal.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"intermediate","question":"A support level is an exact price that guarantees a rebound.","answer":false,"explanation":"Support is a zone of past reactions, not a guaranteed floor or an automatic buy signal.","parameters":{}},"id":{"type":"true_false","difficulty":"intermediate","question":"Level support adalah harga tepat yang menjamin harga akan memantul.","answer":false,"explanation":"Support adalah zona reaksi masa lalu, bukan lantai yang terjamin atau sinyal beli otomatis.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-CHART-03','Reading Trading Charts','chart_literacy','advanced','multiple_choice',$json${"type":"multiple_choice","difficulty":"advanced","question":"A sharp one-day chart move conflicts with a longer-term trend. What is the most disciplined response?","options":["Check the timeframe, thesis, and risk before acting","Assume the one-day move proves the trend reversed","Copy the loudest social-media trade","Ignore your position size"],"answer":"Check the timeframe, thesis, and risk before acting","explanation":"Different timeframes can tell different parts of the story; a chart does not remove uncertainty.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"advanced","question":"A sharp one-day chart move conflicts with a longer-term trend. What is the most disciplined response?","options":["Check the timeframe, thesis, and risk before acting","Assume the one-day move proves the trend reversed","Copy the loudest social-media trade","Ignore your position size"],"answer":"Check the timeframe, thesis, and risk before acting","explanation":"Different timeframes can tell different parts of the story; a chart does not remove uncertainty.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"advanced","question":"Pergerakan grafik satu hari yang tajam bertentangan dengan tren jangka panjang. Apa respons paling disiplin?","options":["Periksa timeframe, tesis, dan risiko sebelum bertindak","Anggap pergerakan satu hari membuktikan tren berbalik","Salin transaksi media sosial yang paling ramai","Abaikan ukuran posisimu"],"answer":"Periksa timeframe, tesis, dan risiko sebelum bertindak","explanation":"Timeframe berbeda dapat menunjukkan bagian cerita yang berbeda; grafik tidak menghilangkan ketidakpastian.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-DECISION-01','Decision Analysis Lab','decision_analysis','beginner','true_false',$json${"type":"true_false","difficulty":"beginner","question":"One candle alone is enough evidence to know what a market will do next.","answer":false,"explanation":"One observation has little context. A sequence, timeframe, and risk plan matter.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"beginner","question":"One candle alone is enough evidence to know what a market will do next.","answer":false,"explanation":"One observation has little context. A sequence, timeframe, and risk plan matter.","parameters":{}},"id":{"type":"true_false","difficulty":"beginner","question":"Satu candle saja cukup sebagai bukti untuk mengetahui langkah pasar berikutnya.","answer":false,"explanation":"Satu pengamatan memiliki sedikit konteks. Rangkaian, timeframe, dan rencana risiko tetap penting.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-DECISION-02','Decision Analysis Lab','decision_analysis','intermediate','multiple_choice',$json${"type":"multiple_choice","difficulty":"intermediate","question":"What should a trade thesis include before you act?","options":["Why the idea may work and what evidence would invalidate it","Only a target profit","A prediction with no risk limit","A popular influencer's opinion"],"answer":"Why the idea may work and what evidence would invalidate it","explanation":"Writing both a reason and an invalidation rule makes later review more honest.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"intermediate","question":"What should a trade thesis include before you act?","options":["Why the idea may work and what evidence would invalidate it","Only a target profit","A prediction with no risk limit","A popular influencer's opinion"],"answer":"Why the idea may work and what evidence would invalidate it","explanation":"Writing both a reason and an invalidation rule makes later review more honest.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"intermediate","question":"Apa yang perlu ada dalam tesis transaksi sebelum bertindak?","options":["Alasan ide mungkin berhasil dan bukti yang membatalkannya","Hanya target keuntungan","Prediksi tanpa batas risiko","Pendapat influencer populer"],"answer":"Alasan ide mungkin berhasil dan bukti yang membatalkannya","explanation":"Menulis alasan dan aturan pembatalan membuat peninjauan berikutnya lebih jujur.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-DECISION-03','Decision Analysis Lab','decision_analysis','advanced','true_false',$json${"type":"true_false","difficulty":"advanced","question":"A high-conviction opinion is a reason to risk money needed for rent or an emergency fund.","answer":false,"explanation":"Conviction does not change the purpose of essential money. Position size must protect the plan.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"advanced","question":"A high-conviction opinion is a reason to risk money needed for rent or an emergency fund.","answer":false,"explanation":"Conviction does not change the purpose of essential money. Position size must protect the plan.","parameters":{}},"id":{"type":"true_false","difficulty":"advanced","question":"Keyakinan yang sangat kuat adalah alasan mempertaruhkan uang untuk sewa atau dana darurat.","answer":false,"explanation":"Keyakinan tidak mengubah tujuan uang pokok. Ukuran posisi harus melindungi rencana.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-UNCERTAINTY-01','Decision Quality Under Uncertainty','decision_quality_uncertainty','beginner','multiple_choice',$json${"type":"multiple_choice","difficulty":"beginner","question":"A good decision under uncertainty is judged mainly by:","options":["The quality of the process and information available","Whether it made a profit immediately","How confident it felt","What strangers predicted"],"answer":"The quality of the process and information available","explanation":"A sound process can have a bad short-term outcome, and a poor process can get lucky.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"beginner","question":"A good decision under uncertainty is judged mainly by:","options":["The quality of the process and information available","Whether it made a profit immediately","How confident it felt","What strangers predicted"],"answer":"The quality of the process and information available","explanation":"A sound process can have a bad short-term outcome, and a poor process can get lucky.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"beginner","question":"Keputusan yang baik di bawah ketidakpastian terutama dinilai dari:","options":["Kualitas proses dan informasi yang tersedia","Apakah langsung menghasilkan untung","Seberapa yakin rasanya","Apa yang diprediksi orang asing"],"answer":"Kualitas proses dan informasi yang tersedia","explanation":"Proses yang baik dapat menghasilkan hasil jangka pendek yang buruk, dan proses buruk bisa beruntung.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-UNCERTAINTY-02','Decision Quality Under Uncertainty','decision_quality_uncertainty','intermediate','true_false',$json${"type":"true_false","difficulty":"intermediate","question":"A single winning trade proves that the decision process was sound.","answer":false,"explanation":"Outcomes contain luck. Review the evidence, risk, and alternatives rather than only the result.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"intermediate","question":"A single winning trade proves that the decision process was sound.","answer":false,"explanation":"Outcomes contain luck. Review the evidence, risk, and alternatives rather than only the result.","parameters":{}},"id":{"type":"true_false","difficulty":"intermediate","question":"Satu transaksi yang untung membuktikan proses pengambilan keputusan sudah baik.","answer":false,"explanation":"Hasil mengandung keberuntungan. Tinjau bukti, risiko, dan alternatif, bukan hanya hasilnya.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-UNCERTAINTY-03','Decision Quality Under Uncertainty','decision_quality_uncertainty','advanced','multiple_choice',$json${"type":"multiple_choice","difficulty":"advanced","question":"What best reduces overconfidence before an uncertain decision?","options":["Write what would change your mind and seek disconfirming evidence","Increase the stake when you feel certain","Read only sources that agree with you","Treat a forecast as a guarantee"],"answer":"Write what would change your mind and seek disconfirming evidence","explanation":"Looking for contrary evidence creates a deliberate check against one-sided stories.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"advanced","question":"What best reduces overconfidence before an uncertain decision?","options":["Write what would change your mind and seek disconfirming evidence","Increase the stake when you feel certain","Read only sources that agree with you","Treat a forecast as a guarantee"],"answer":"Write what would change your mind and seek disconfirming evidence","explanation":"Looking for contrary evidence creates a deliberate check against one-sided stories.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"advanced","question":"Apa yang paling mengurangi overconfidence sebelum keputusan yang tidak pasti?","options":["Tulis apa yang dapat mengubah pikiranmu dan cari bukti yang berlawanan","Naikkan ukuran posisi saat merasa pasti","Baca hanya sumber yang sependapat","Anggap proyeksi sebagai jaminan"],"answer":"Tulis apa yang dapat mengubah pikiranmu dan cari bukti yang berlawanan","explanation":"Mencari bukti berlawanan menjadi pemeriksaan sengaja terhadap cerita yang sepihak.","parameters":{}}}}$json$::jsonb,TRUE)
ON CONFLICT (id) DO UPDATE SET chapter=EXCLUDED.chapter,topic=EXCLUDED.topic,difficulty=EXCLUDED.difficulty,type=EXCLUDED.type,body=EXCLUDED.body,is_active=TRUE;

INSERT INTO daily_focus_questions (id, chapter, topic, difficulty, type, body, is_active) VALUES
('DF2-KO252-OPS-01','Personal Finance Operations','personal_finance_operations','beginner','multiple_choice',$json${"type":"multiple_choice","difficulty":"beginner","question":"Why is it useful to review your account transactions regularly?","options":["To spot errors, fraud, and forgotten recurring charges","To make every day a shopping day","To avoid knowing your balance","To guarantee investment returns"],"answer":"To spot errors, fraud, and forgotten recurring charges","explanation":"A regular review makes small operational problems visible before they become expensive.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"beginner","question":"Why is it useful to review your account transactions regularly?","options":["To spot errors, fraud, and forgotten recurring charges","To make every day a shopping day","To avoid knowing your balance","To guarantee investment returns"],"answer":"To spot errors, fraud, and forgotten recurring charges","explanation":"A regular review makes small operational problems visible before they become expensive.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"beginner","question":"Mengapa bermanfaat meninjau transaksi rekening secara rutin?","options":["Untuk menemukan kesalahan, penipuan, dan biaya berulang yang terlupakan","Agar setiap hari menjadi hari belanja","Untuk menghindari mengetahui saldo","Untuk menjamin imbal hasil investasi"],"answer":"Untuk menemukan kesalahan, penipuan, dan biaya berulang yang terlupakan","explanation":"Peninjauan rutin membuat masalah operasional kecil terlihat sebelum menjadi mahal.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-OPS-02','Personal Finance Operations','personal_finance_operations','intermediate','true_false',$json${"type":"true_false","difficulty":"intermediate","question":"Separating bill money from spending money can reduce the chance of missing essential payments.","answer":true,"explanation":"Separate buckets make the purpose of money clear and reduce accidental overspending.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"intermediate","question":"Separating bill money from spending money can reduce the chance of missing essential payments.","answer":true,"explanation":"Separate buckets make the purpose of money clear and reduce accidental overspending.","parameters":{}},"id":{"type":"true_false","difficulty":"intermediate","question":"Memisahkan uang tagihan dari uang belanja dapat mengurangi kemungkinan melewatkan pembayaran penting.","answer":true,"explanation":"Pos terpisah memperjelas tujuan uang dan mengurangi belanja berlebihan yang tidak disengaja.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-OPS-03','Personal Finance Operations','personal_finance_operations','advanced','multiple_choice',$json${"type":"multiple_choice","difficulty":"advanced","question":"Your bank balance is lower than expected. What is the best first response?","options":["Reconcile recent transactions before moving money or blaming a charge","Immediately borrow to cover it","Ignore it until next month","Share your banking password for help"],"answer":"Reconcile recent transactions before moving money or blaming a charge","explanation":"Verify the facts first: pending payments, subscriptions, mistakes, or suspicious activity can look similar.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"advanced","question":"Your bank balance is lower than expected. What is the best first response?","options":["Reconcile recent transactions before moving money or blaming a charge","Immediately borrow to cover it","Ignore it until next month","Share your banking password for help"],"answer":"Reconcile recent transactions before moving money or blaming a charge","explanation":"Verify the facts first: pending payments, subscriptions, mistakes, or suspicious activity can look similar.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"advanced","question":"Saldo bankmu lebih rendah dari perkiraan. Apa respons pertama terbaik?","options":["Rekonsiliasi transaksi terbaru sebelum memindahkan uang atau menyalahkan sebuah tagihan","Segera berutang untuk menutupinya","Abaikan sampai bulan depan","Bagikan kata sandi bank untuk meminta bantuan"],"answer":"Rekonsiliasi transaksi terbaru sebelum memindahkan uang atau menyalahkan sebuah tagihan","explanation":"Verifikasi fakta terlebih dahulu: pembayaran tertunda, langganan, kesalahan, atau aktivitas mencurigakan bisa tampak serupa.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-EVIDENCE-01','Evidence-Based Investing Decisions','evidence_based_investing','beginner','true_false',$json${"type":"true_false","difficulty":"beginner","question":"A social-media post is enough research to decide whether to buy an investment.","answer":false,"explanation":"A post can be a starting point for questions, not enough evidence for a financial decision.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"beginner","question":"A social-media post is enough research to decide whether to buy an investment.","answer":false,"explanation":"A post can be a starting point for questions, not enough evidence for a financial decision.","parameters":{}},"id":{"type":"true_false","difficulty":"beginner","question":"Unggahan media sosial sudah cukup sebagai riset untuk memutuskan membeli investasi.","answer":false,"explanation":"Unggahan dapat menjadi awal pertanyaan, bukan bukti yang cukup untuk keputusan keuangan.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-EVIDENCE-02','Evidence-Based Investing Decisions','evidence_based_investing','intermediate','multiple_choice',$json${"type":"multiple_choice","difficulty":"intermediate","question":"Which source is most useful for checking a listed company's own financial claims?","options":["Its official filings and audited reports","An anonymous chat-room tip","A cropped price chart","A promise of guaranteed return"],"answer":"Its official filings and audited reports","explanation":"Primary disclosures and audited reports are stronger evidence than unverified commentary.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"intermediate","question":"Which source is most useful for checking a listed company's own financial claims?","options":["Its official filings and audited reports","An anonymous chat-room tip","A cropped price chart","A promise of guaranteed return"],"answer":"Its official filings and audited reports","explanation":"Primary disclosures and audited reports are stronger evidence than unverified commentary.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"intermediate","question":"Sumber mana paling berguna untuk memeriksa klaim keuangan perusahaan tercatat?","options":["Keterbukaan resmi dan laporan auditnya","Tips anonim di ruang obrolan","Grafik harga yang dipotong","Janji imbal hasil terjamin"],"answer":"Keterbukaan resmi dan laporan auditnya","explanation":"Keterbukaan primer dan laporan audit adalah bukti lebih kuat daripada komentar yang tidak terverifikasi.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-EVIDENCE-03','Evidence-Based Investing Decisions','evidence_based_investing','advanced','multiple_choice',$json${"type":"multiple_choice","difficulty":"advanced","question":"Two credible sources disagree about an investment. What should you do?","options":["Compare their evidence, assumptions, date, and incentives before deciding","Choose the more confident headline","Treat disagreement as proof of fraud","Double the position immediately"],"answer":"Compare their evidence, assumptions, date, and incentives before deciding","explanation":"Good research weighs source quality and explains uncertainty instead of pretending it is absent.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"advanced","question":"Two credible sources disagree about an investment. What should you do?","options":["Compare their evidence, assumptions, date, and incentives before deciding","Choose the more confident headline","Treat disagreement as proof of fraud","Double the position immediately"],"answer":"Compare their evidence, assumptions, date, and incentives before deciding","explanation":"Good research weighs source quality and explains uncertainty instead of pretending it is absent.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"advanced","question":"Dua sumber kredibel berbeda pendapat tentang sebuah investasi. Apa yang harus dilakukan?","options":["Bandingkan bukti, asumsi, tanggal, dan insentifnya sebelum memutuskan","Pilih judul yang paling percaya diri","Anggap perbedaan sebagai bukti penipuan","Segera gandakan posisi"],"answer":"Bandingkan bukti, asumsi, tanggal, dan insentifnya sebelum memutuskan","explanation":"Riset yang baik menimbang kualitas sumber dan menjelaskan ketidakpastian, bukan berpura-pura tidak ada.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-OWNERSHIP-01','Ownership, Enterprise & Income Quality','ownership_income_quality','beginner','multiple_choice',$json${"type":"multiple_choice","difficulty":"beginner","question":"Owning a share generally means you own:","options":["A small claim on a company's ownership and results","A guaranteed loan repayment","A fixed bank deposit","A promise of profit"],"answer":"A small claim on a company's ownership and results","explanation":"Shareholders own a fractional interest; dividends and prices are not guaranteed.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"beginner","question":"Owning a share generally means you own:","options":["A small claim on a company's ownership and results","A guaranteed loan repayment","A fixed bank deposit","A promise of profit"],"answer":"A small claim on a company's ownership and results","explanation":"Shareholders own a fractional interest; dividends and prices are not guaranteed.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"beginner","question":"Memiliki satu saham umumnya berarti kamu memiliki:","options":["Klaim kecil atas kepemilikan dan hasil perusahaan","Pelunasan pinjaman yang terjamin","Deposito bank tetap","Janji keuntungan"],"answer":"Klaim kecil atas kepemilikan dan hasil perusahaan","explanation":"Pemegang saham memiliki kepentingan sebagian; dividen dan harga tidak dijamin.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-OWNERSHIP-02','Ownership, Enterprise & Income Quality','ownership_income_quality','intermediate','true_false',$json${"type":"true_false","difficulty":"intermediate","question":"A company can report revenue growth while still having weak cash flow or rising debt.","answer":true,"explanation":"Revenue is only one measure. Cash generation, margins, debt, and sustainability also matter.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"intermediate","question":"A company can report revenue growth while still having weak cash flow or rising debt.","answer":true,"explanation":"Revenue is only one measure. Cash generation, margins, debt, and sustainability also matter.","parameters":{}},"id":{"type":"true_false","difficulty":"intermediate","question":"Perusahaan dapat melaporkan pertumbuhan pendapatan sambil tetap memiliki arus kas lemah atau utang yang naik.","answer":true,"explanation":"Pendapatan hanya satu ukuran. Penciptaan kas, margin, utang, dan keberlanjutan juga penting.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-OWNERSHIP-03','Ownership, Enterprise & Income Quality','ownership_income_quality','advanced','multiple_choice',$json${"type":"multiple_choice","difficulty":"advanced","question":"What is the most useful way to assess the quality of a company's income?","options":["Look beyond one headline to cash flow, margins, debt, and repeatability","Use only today's price change","Assume all revenue is equally durable","Ignore company disclosures"],"answer":"Look beyond one headline to cash flow, margins, debt, and repeatability","explanation":"Income quality asks whether earnings are supported by durable operations and cash, not just a single number.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"advanced","question":"What is the most useful way to assess the quality of a company's income?","options":["Look beyond one headline to cash flow, margins, debt, and repeatability","Use only today's price change","Assume all revenue is equally durable","Ignore company disclosures"],"answer":"Look beyond one headline to cash flow, margins, debt, and repeatability","explanation":"Income quality asks whether earnings are supported by durable operations and cash, not just a single number.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"advanced","question":"Cara paling berguna menilai kualitas pendapatan perusahaan adalah:","options":["Melihat lebih dari satu judul ke arus kas, margin, utang, dan keberulangan","Hanya memakai perubahan harga hari ini","Menganggap semua pendapatan sama tahan lamanya","Mengabaikan keterbukaan perusahaan"],"answer":"Melihat lebih dari satu judul ke arus kas, margin, utang, dan keberulangan","explanation":"Kualitas pendapatan menanyakan apakah laba didukung operasi dan kas yang tahan lama, bukan hanya satu angka.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-BIAS-01','Bias-Resistant Decisions & Resilience','bias_resilience','beginner','true_false',$json${"type":"true_false","difficulty":"beginner","question":"Confirmation bias means looking for information that supports your belief and ignoring contrary evidence.","answer":true,"explanation":"Naming the bias makes it easier to deliberately seek a balanced view.","parameters":{},"locales":{"en":{"type":"true_false","difficulty":"beginner","question":"Confirmation bias means looking for information that supports your belief and ignoring contrary evidence.","answer":true,"explanation":"Naming the bias makes it easier to deliberately seek a balanced view.","parameters":{}},"id":{"type":"true_false","difficulty":"beginner","question":"Bias konfirmasi berarti mencari informasi yang mendukung keyakinanmu dan mengabaikan bukti yang berlawanan.","answer":true,"explanation":"Mengenali bias membuat lebih mudah untuk sengaja mencari pandangan yang seimbang.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-BIAS-02','Bias-Resistant Decisions & Resilience','bias_resilience','intermediate','multiple_choice',$json${"type":"multiple_choice","difficulty":"intermediate","question":"After an investment loss, what action best supports resilience?","options":["Review the process and risk limit before making another decision","Chase a faster trade to win it back","Hide the loss and stop checking facts","Increase risk because you are angry"],"answer":"Review the process and risk limit before making another decision","explanation":"A pause and review prevent one loss from turning into a sequence of impulsive decisions.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"intermediate","question":"After an investment loss, what action best supports resilience?","options":["Review the process and risk limit before making another decision","Chase a faster trade to win it back","Hide the loss and stop checking facts","Increase risk because you are angry"],"answer":"Review the process and risk limit before making another decision","explanation":"A pause and review prevent one loss from turning into a sequence of impulsive decisions.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"intermediate","question":"Setelah rugi investasi, tindakan mana paling mendukung ketahanan?","options":["Tinjau proses dan batas risiko sebelum membuat keputusan lagi","Kejar transaksi cepat untuk mengembalikan kerugian","Sembunyikan kerugian dan berhenti memeriksa fakta","Naikkan risiko karena marah"],"answer":"Tinjau proses dan batas risiko sebelum membuat keputusan lagi","explanation":"Jeda dan tinjauan mencegah satu kerugian berubah menjadi rangkaian keputusan impulsif.","parameters":{}}}}$json$::jsonb,TRUE),
('DF2-KO252-BIAS-03','Bias-Resistant Decisions & Resilience','bias_resilience','advanced','multiple_choice',$json${"type":"multiple_choice","difficulty":"advanced","question":"Which pre-commitment best protects against revenge trading?","options":["Set a loss limit and a pause rule before placing any trade","Promise to trade more after a loss","Follow real-time hype without a plan","Remove all records of past trades"],"answer":"Set a loss limit and a pause rule before placing any trade","explanation":"Rules written before emotion rises protect decision quality when outcomes are stressful.","parameters":{},"locales":{"en":{"type":"multiple_choice","difficulty":"advanced","question":"Which pre-commitment best protects against revenge trading?","options":["Set a loss limit and a pause rule before placing any trade","Promise to trade more after a loss","Follow real-time hype without a plan","Remove all records of past trades"],"answer":"Set a loss limit and a pause rule before placing any trade","explanation":"Rules written before emotion rises protect decision quality when outcomes are stressful.","parameters":{}},"id":{"type":"multiple_choice","difficulty":"advanced","question":"Komitmen awal mana paling melindungi dari revenge trading?","options":["Tetapkan batas rugi dan aturan jeda sebelum melakukan transaksi","Berjanji bertransaksi lebih banyak setelah rugi","Ikuti hype waktu nyata tanpa rencana","Hapus semua catatan transaksi sebelumnya"],"answer":"Tetapkan batas rugi dan aturan jeda sebelum melakukan transaksi","explanation":"Aturan yang ditulis sebelum emosi meningkat melindungi kualitas keputusan saat hasil terasa menekan.","parameters":{}}}}$json$::jsonb,TRUE)
ON CONFLICT (id) DO UPDATE SET chapter=EXCLUDED.chapter,topic=EXCLUDED.topic,difficulty=EXCLUDED.difficulty,type=EXCLUDED.type,body=EXCLUDED.body,is_active=TRUE;
