-- Earlier locale migrations stored only the Indonesian override. Normalise every
-- active row to the explicit two-variant contract without nesting `locales`.
UPDATE daily_focus_questions
SET body = jsonb_set(
  body,
  '{locales}',
  COALESCE(body->'locales', '{}'::jsonb) || jsonb_build_object('en', body - 'locales'),
  TRUE
)
WHERE is_active
  AND (NOT (body ? 'locales') OR NOT (body->'locales' ? 'en'));

DO $$
DECLARE
  v_missing_locales INTEGER;
  v_missing_late_chapters INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_missing_locales
  FROM daily_focus_questions
  WHERE is_active
    AND (NOT (body ? 'locales') OR NOT (body->'locales' ? 'en') OR NOT (body->'locales' ? 'id'));

  IF v_missing_locales <> 0 THEN
    RAISE EXCEPTION 'KO-252 requires EN and ID payloads for every active Daily Focus question; % remain incomplete', v_missing_locales;
  END IF;

  SELECT COUNT(*) INTO v_missing_late_chapters
  FROM (
    SELECT chapter
    FROM daily_focus_questions
    WHERE is_active
      AND chapter IN (
        'Reading Trading Charts',
        'Decision Analysis Lab',
        'Decision Quality Under Uncertainty',
        'Personal Finance Operations',
        'Evidence-Based Investing Decisions',
        'Ownership, Enterprise & Income Quality',
        'Bias-Resistant Decisions & Resilience'
      )
    GROUP BY chapter
    HAVING COUNT(*) < 3
  ) uncovered;

  IF v_missing_late_chapters <> 0 THEN
    RAISE EXCEPTION 'KO-252 requires at least three Daily Focus prompts per published later chapter; % chapters remain under-covered', v_missing_late_chapters;
  END IF;
END;
$$;

COMMIT;
